'use strict';
const E=PairEngine,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const templates=[['NVDA','AMD','Semiconductors'],['GOOGL','META','Digital advertising'],['MSFT','GOOGL','Cloud & software'],['XAU','XAG','Precious metals'],['SPX','NDX','US equity indices']];
let venue='Popdex',page='scanner',selected=0,imported=[],lastResult=null,editId=null;
let journal=[];try{journal=JSON.parse(localStorage.getItem('pairdesk-journal-v1')||'[]');if(!Array.isArray(journal))journal=[];}catch{$('storage-status').textContent='Journal storage unavailable';}
const demos=templates.map((p,i)=>({a:p[0],b:p[1],sector:p[2],rows:E.demo(4+i*17),kind:'Synthetic demo',demo:true}));
const list=()=>{const arr=imported.filter(x=>x.venue===venue);return arr.length?arr:demos;};
const current=()=>list()[selected]||list()[0];
const fmt=(v,n=2)=>Number.isFinite(v)?v.toFixed(n):'—',money=v=>Number.isFinite(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v):'—';
const date=t=>new Date(t).toISOString().replace('T',' ').slice(0,16);
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000);}
function metric(label,value,sub){return `<div class="metric"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`;}
function show(p){page=p;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('hidden',x.id!==p));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const t={auto:['Auto scanner','Let the pairs come to you.','Automatic intraday research across Popdex, Arcus and Variational.'],live:['Exchange data','Real markets. Clear provenance.','Public venue prices and funding, with historical coverage stated explicitly.'],scanner:['Pair scanner','Find the divergence.','Explore related assets. Test the spread. Keep both legs together.'],backtest:['Backtester','Put the spread to the test.','Understand the assumptions behind every result.'],journal:['Trade journal','Two legs. One thesis.','Record the trade, track the outcome, learn from the pair.'],data:['Data & methods','Know what’s behind the signal.','Bring venue prices and keep data provenance visible.']}[p];$('breadcrumb').textContent=t[0];$('title').textContent=t[1];$('subtitle').textContent=t[2];if(p==='live'&&typeof renderFeed==='function')renderFeed();if(p==='journal')renderJournal();if(p==='backtest')$('bt-pair').textContent=`${venue} · ${current().a} / ${current().b}`;}
function plot(target,series,rows){const w=900,h=210,left=60,right=18,top=15,bottom=32,values=series.flatMap(s=>s.values),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo)*.14||1,min=lo-pad,max=hi+pad;const x=i=>left+i/(rows.length-1)*(w-left-right),y=v=>top+(max-v)/(max-min)*(h-top-bottom);let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${target==='price-chart'?'Relative price performance':'Backtest P and L'}"><title>${target==='price-chart'?'Rebased prices':'Estimated P&L'}</title>`;for(let i=0;i<4;i++){const v=min+i/3*(max-min);svg+=`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#edf0f3" stroke-dasharray="3 5"/><text x="${left-12}" y="${y(v)+4}" text-anchor="end" fill="#98a2ab" font-size="10">${v.toFixed(1)}</text>`;}for(const s of series){const step=Math.max(1,Math.floor(s.values.length/1300));let indices=[];for(let i=0;i<s.values.length;i+=step)indices.push(i);if(indices.at(-1)!==s.values.length-1)indices.push(s.values.length-1);svg+=`<path d="${indices.map((i,j)=>`${j?'L':'M'}${x(i).toFixed(2)},${y(s.values[i]).toFixed(2)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="1.8"/>`;}for(let i=0;i<4;i++){let ix=Math.round(i/3*(rows.length-1));svg+=`<text x="${x(ix)}" y="${h-5}" text-anchor="${i===0?'start':i===3?'end':'middle'}" fill="#98a2ab" font-size="10">${date(rows[ix].t).slice(5)}</text>`;}$ (target).innerHTML=svg+'</svg>';$ (target).classList.remove('empty');}
function render(){const pairs=list(),p=current(),s=E.stats(p.rows),rank=pairs.map((p,i)=>({p,i,s:E.stats(p.rows)})).sort((a,b)=>Math.abs(b.s?.z||0)-Math.abs(a.s?.z||0));$('source-pill').textContent='● '+p.kind;$('notice').textContent=p.demo?'DEMO WORKSPACE — Generated prices illustrate the workflow. These are not live signals or verified venue listings. Import exchange prices to research your own pairs.':`${p.kind} · ${p.connected?'Fetched from':'User-supplied'} ${venue} data · ${p.rows.length.toLocaleString()} rows · Last bar ${date(p.rows.at(-1).t)} UTC. Historical data, not a live signal.`;
$('metrics').innerHTML=metric('Pairs in view',String(pairs.length).padStart(2,'0'),p.demo?'Illustrative pair universe':'Imported for '+esc(venue))+metric('Divergence ≥ 2σ',rank.filter(x=>Math.abs(x.s?.z||0)>=2).length,'Research flags, not entries')+metric('Signal / context','5m <span style="color:#a2abb2;font-size:18px">/ 15m</span>','60-bar / 20-bar lookbacks')+metric('Data coverage',p.demo?'Demo':p.connected?'Exchange':'Imported',p.demo?'Synthetic historical sample':p.connected?'Completed historical bars':'User-supplied prices');
const query=$('search').value.toLowerCase();$('pairs').innerHTML=rank.filter(x=>(x.p.a+x.p.b+x.p.sector).toLowerCase().includes(query)).map(({p,i,s})=>`<tr class="pair-row ${i===selected?'chosen':''}" data-index="${i}" tabindex="0" aria-label="Select ${esc(p.a)} and ${esc(p.b)}"><td><span class="pair-title">${esc(p.a)} <span style="font-weight:400;color:#a5afb7">/</span> ${esc(p.b)}</span><span class="pair-sub">${esc(p.sector)}</span></td><td><span class="number zbar ${Math.abs(s?.z||0)>=2?'warm':''}">${fmt(s?.z)}</span></td><td class="number">${fmt(s?.correlation)}</td><td class="number">${fmt(s?.confirm)}</td><td><span class="pill">${!s?'Insufficient fit':Math.abs(s.z)>=2?'Diverging':'Within range'}</span></td></tr>`).join('')||'<tr><td colspan="5">No matching pairs.</td></tr>';
$('selected-name').textContent=`${p.a} / ${p.b}`;$('pair-summary').innerHTML=`<div class="stat-line">5m spread z-score <strong>${fmt(s?.z)}</strong></div><div class="stat-line">Log hedge ratio β <strong>${fmt(s?.beta,3)}</strong></div><div class="stat-line">Return correlation <strong>${fmt(s?.correlation)}</strong></div><div class="stat-line">15m confirmation z <strong>${fmt(s?.confirm)}</strong></div><p class="detail-note">${!s?'No stable positive-beta fit for this window.':s.z>0?'A sits above its fitted relationship with B.':'A sits below its fitted relationship with B.'} Review the history and execution costs before forming a trade thesis.</p>`;
$('legend').innerHTML=`<span class="key" style="background:#27866d"></span>${esc(p.a)}<span class="key" style="background:#9588cb"></span>${esc(p.b)}`;plot('price-chart',[{values:p.rows.map(r=>100*r.a/p.rows[0].a),color:'#27866d'},{values:p.rows.map(r=>100*r.b/p.rows[0].b),color:'#9588cb'}],p.rows);$('bt-pair').textContent=`${venue} · ${p.a} / ${p.b}`;$('import-venue').textContent=venue;const foot=document.querySelector('#scanner .panel-foot');foot.textContent=p.demo?'Demo symbols are examples; exchange availability is unverified.':p.connected?'Actual venue symbols. Historical research does not verify an executable trade.':'User-imported symbols; instrument identity is user-supplied.';}
function resetResult(){lastResult=null;$('bt-results').innerHTML='';$('equity-chart').textContent='Run a backtest to see results.';$('equity-chart').classList.add('empty');$('bt-trades').innerHTML='';$('export-bt').disabled=true;}
function choose(i){selected=i;resetResult();render();}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const csvCell=v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
function csv(rows){return rows.map(r=>r.map(csvCell).join(',')).join('\n');}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.page));document.querySelectorAll('[data-venue]').forEach(b=>b.onclick=()=>{venue=b.dataset.venue;selected=0;document.querySelectorAll('[data-venue]').forEach(x=>x.classList.toggle('selected',x===b));resetResult();render();if(page==='journal')renderJournal();if(page==='live'&&typeof renderFeed==='function')renderFeed();});
$('pairs').onclick=e=>{const tr=e.target.closest('[data-index]');if(tr)choose(+tr.dataset.index);};$('pairs').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){const tr=e.target.closest('[data-index]');if(tr){e.preventDefault();choose(+tr.dataset.index);}}};$('search').oninput=render;$('import-top').onclick=()=>show('data');$('test-pair').onclick=()=>show('backtest');
$('bt-form').onsubmit=e=>{e.preventDefault();const o={window:+$('lookback').value,entry:+$('entry').value,exit:+$('exit').value,stop:+$('stop').value,hold:+$('hold').value,gross:+$('gross').value,cost:+$('cost').value,funding:+$('funding').value,confirm:$('confirm').checked};if(o.exit>=o.entry||o.stop<=o.entry){toast('Use exit < entry < stop.');return;}if(current().rows.length<=o.window+2){toast('Not enough rows for this lookback.');return;}const result=E.backtest(current().rows,o);lastResult={...result,pair:current(),venue,options:o};$('bt-results').innerHTML=metric('Net P&L',money(result.net),current().demo?'Synthetic result':'Estimated costs included')+metric('Max drawdown',money(result.drawdown),'Marked-to-market dollars')+metric('Completed trades',result.trades.length,'Both legs combined')+metric('Win rate',result.win===null?'—':fmt(result.win*100,1)+'%','After estimated costs');plot('equity-chart',[{values:result.equity.map(x=>x.v),color:'#27866d'}],result.equity);$('bt-trades').innerHTML=result.trades.slice(-100).reverse().map(t=>`<tr><td class="number">${date(t.t)}</td><td>${t.side===1?'Long A / Short B':'Short A / Long B'}</td><td>${t.reason}</td><td class="number ${t.net>=0?'positive':'negative'}">${money(t.net)}</td></tr>`).join('')||'<tr><td colspan="4">No trades met these rules in this sample.</td></tr>';$('export-bt').disabled=false;};
$('export-bt').onclick=()=>{if(!lastResult)return;const r=lastResult;download('pairdesk-backtest.csv',csv([['venue','source','asset_a','asset_b','entry_utc','exit_utc','direction','beta','quantity_a','quantity_b','net_pnl','reason','gross','cost_bps','funding_bps_day','lookback','entry_z','exit_z','stop_z','max_hold','confirm_15m'],...r.trades.map(t=>[r.venue,r.pair.kind,r.pair.a,r.pair.b,date(t.t),date(t.exit),t.side,t.f.beta,t.qa,t.qb,t.net,t.reason,r.options.gross,r.options.cost,r.options.funding,r.options.window,r.options.entry,r.options.exit,r.options.stop,r.options.hold,r.options.confirm])]));};
$('import-form').onsubmit=async e=>{e.preventDefault();const a=$('symbol-a').value.trim().toUpperCase(),b=$('symbol-b').value.trim().toUpperCase(),targetVenue=venue,kind=$('data-kind').value;try{if(a===b)throw Error('Choose two different assets.');const file=$('csv-file').files[0];if(file.size>8000000)throw Error('File exceeds 8 MB.');const rows=E.parseCSV(await file.text());const gaps=rows.filter((r,i)=>i&&r.t-rows[i-1].t>300000).length;imported.push({a,b,rows,venue:targetVenue,sector:'User-imported · '+kind,kind,demo:false});if(venue===targetVenue)selected=list().length-1;resetResult();render();$('import-status').textContent=`Imported ${rows.length.toLocaleString()} bars into ${targetVenue}. ${gaps} gaps longer than 5 minutes. Data is available until reload.`;toast('Pair imported. Find it in the scanner.');}catch(err){$('import-status').textContent=err.message;}};
$('sample-csv').onclick=()=>download('pairdesk-synthetic-example.csv','timestamp,asset_a,asset_b\n'+E.demo(4).map(r=>[new Date(r.t).toISOString(),r.a.toFixed(6),r.b.toFixed(6)].join(',')).join('\n'));
function saveJournal(next){try{localStorage.setItem('pairdesk-journal-v1',JSON.stringify(next));journal=next;return true;}catch{ $('journal-error').textContent='Could not save. Browser storage is unavailable or full.';toast('Journal was not saved. Browser storage is unavailable.');return false;}}
function journalPnl(t){return t.xa!==null&&t.xb!==null?t.dir*(t.qa*(t.xa-t.pa)-t.qb*(t.xb-t.pb))-t.cost:null;}
function renderJournal(){const records=journal.filter(t=>t.venue===venue);$('journal-list').innerHTML=records.length?records.slice().reverse().map(t=>{const pnl=journalPnl(t);return `<article class="panel journal-card"><div class="panel-head"><div><h2>${esc(t.a)} / ${esc(t.b)}</h2><small>${esc(t.venue)} · ${esc(t.time.replace('T',' '))} UTC</small></div><span class="pill">${pnl===null?'Open record':'Closed'}</span></div><div class="values"><span>DIRECTION<strong>${t.dir===1?'Long A / Short B':'Short A / Long B'}</strong></span><span>ENTRY PRICES<strong>${fmt(t.pa)} / ${fmt(t.pb)}</strong></span><span>NET REALIZED P&L<strong>${money(pnl)}</strong></span></div><p>${esc(t.notes||'No thesis recorded.')}</p><button class="secondary" data-edit="${esc(t.id)}">${pnl===null?'Update / close':'Edit record'}</button> <button class="secondary" data-delete="${esc(t.id)}">Delete</button></article>`;}).join(''):'<article class="panel padded"><h2>A place for the whole trade.</h2><p>No trades recorded for '+esc(venue)+'. Add both legs, your entry prices and your thesis. Update with exit prices to calculate combined realized P&L.</p></article>';}
function openTrade(t){editId=t?.id||null;$('trade-form').reset();const p=current();$('journal-context').textContent=`${t?.venue||venue} · both legs on the same venue`;$('ja').value=t?.a||p.a;$('jb').value=t?.b||p.b;$('jtime').value=t?.time||new Date().toISOString().slice(0,16);if(t){for(const key of ['pa','pb','qa','qb','xa','xb','cost','notes'])$('j'+key).value=t[key]??'';$('jdir').value=t.dir;}$('journal-error').textContent='';$('trade-dialog').showModal();}
$('add-trade').onclick=()=>openTrade();$('journal-pair').onclick=()=>openTrade();$('close-dialog').onclick=()=>$('trade-dialog').close();$('journal-list').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)openTrade(journal.find(t=>t.id===edit.dataset.edit));if(del&&confirm('Delete this paired-trade record?')){if(saveJournal(journal.filter(t=>t.id!==del.dataset.delete)))renderJournal();}};
$('trade-form').onsubmit=e=>{e.preventDefault();const xa=$('jxa').value,xb=$('jxb').value;if((xa==='')!==(xb==='')){$('journal-error').textContent='Enter both exit prices, or leave both blank.';return;}if($('ja').value.trim().toUpperCase()===$('jb').value.trim().toUpperCase()){$('journal-error').textContent='The two assets must be different.';return;}const old=journal.find(t=>t.id===editId),t={id:editId||crypto.randomUUID(),venue:old?.venue||venue,a:$('ja').value.trim().toUpperCase(),b:$('jb').value.trim().toUpperCase(),time:$('jtime').value,dir:+$('jdir').value,pa:+$('jpa').value,pb:+$('jpb').value,qa:+$('jqa').value,qb:+$('jqb').value,xa:xa===''?null:+xa,xb:xb===''?null:+xb,cost:+$('jcost').value,notes:$('jnotes').value};const next=editId?journal.map(x=>x.id===editId?t:x):[...journal,t];if(saveJournal(next)){$('trade-dialog').close();renderJournal();toast('Paired trade saved in this browser.');}};
$('export-journal').onclick=()=>download('pairdesk-journal.csv',csv([['venue','asset_a','asset_b','entry_utc','direction','price_a','price_b','qty_a','qty_b','exit_a','exit_b','cost','net_pnl','notes'],...journal.map(t=>[t.venue,t.a,t.b,t.time,t.dir,t.pa,t.pb,t.qa,t.qb,t.xa,t.xb,t.cost,journalPnl(t),t.notes])]));
$('fetch-live').onclick=()=>{venue='Variational';document.querySelectorAll('[data-venue]').forEach(b=>b.classList.toggle('selected',b.dataset.venue===venue));selected=0;resetResult();render();show('live');};
render();show('scanner');
